# Разбор кода: Лабораторная работа 1 (Вариант 27)

Ниже представлен полный исходный код из `main.cpp` для удобного ознакомления.
В последующих разделах этот код разбит на логические блоки с детальным теоретическим объяснением каждого из них.

## Полный исходный код программы
```cpp
#include <iostream>
#include <vector>
#include <string>

using namespace std;

class Racehorse {
private:
    string nickname;
    double records[5];

public:
    Racehorse(string n, double r1, double r2, double r3, double r4, double r5) {
        nickname = n;
        records[0] = r1; records[1] = r2; records[2] = r3;
        records[3] = r4; records[4] = r5;
    }

    double getAverageTime() const {
        double sum = 0;
        for (int i = 0; i < 5; ++i) sum += records[i];
        return sum / 5.0;
    }

    string getNickname() const { return nickname; }

    void print() const {
        cout << "Кличка: " << nickname << ", Рекорды:";
        for (int i = 0; i < 5; ++i) cout << " " << records[i];
        cout << ", Среднее: " << getAverageTime() << " с" << endl;
    }
};

int main() {
    setlocale(LC_ALL, "Russian");

    vector<Racehorse> horses = {
        Racehorse("Буран", 62.5, 63.1, 61.8, 64.0, 62.0),
        Racehorse("Стрела", 58.2, 59.0, 57.5, 60.1, 58.8),
        Racehorse("Гром", 65.0, 64.3, 66.1, 63.5, 65.7),
        Racehorse("Вихрь", 60.0, 61.2, 59.8, 60.5, 61.0),
        Racehorse("Молния", 55.3, 56.0, 54.8, 55.9, 56.2)
    };

    cout << "Все лошади:" << endl;
    for (const auto& h : horses) {
        h.print();
    }

    double totalAvg = 0;
    for (const auto& h : horses) {
        totalAvg += h.getAverageTime();
    }
    totalAvg /= horses.size();

    cout << "\nСреднее время по всей конюшне: " << totalAvg << " с" << endl;

    return 0;
}

```

---

## 1. Класс `Racehorse`

```cpp
class Racehorse {
private:
    ...
```
- Ключевое слово **`class`** объявляет новый тип данных.
- Блок **`private:`** означает, что поля закрыты от прямого доступа извне (из функции `main`). Это принцип **инкапсуляции**. Мы не можем в `main` написать: `obj.field = 5;`.

```cpp
public:
    Racehorse(...) {
        ...
    }
```
- Блок **`public:`** содержит методы, доступные всем.
- Метод `Racehorse(...)` без типа возвращаемого значения и с именем, совпадающим с именем класса, называется **конструктором**. Он вызывается автоматически при создании объекта. Его задача — проинициализировать приватные переменные переданными значениями.

### Методы класса
- **Геттеры** (`get...()`): так как поля `private`, для чтения их значений снаружи пишутся специальные функции-читатели.
- **`print()`**: выводит все параметры объекта в консоль.
- Ключевое слово **`const`** в конце метода означает, что он **не изменяет** внутреннее состояние (поля) объекта, а только читает их.

## 2. Главная функция `main`

```cpp
    setlocale(LC_ALL, "Russian");
```
- Устанавливает кодовую страницу для консоли Windows, чтобы кириллица выводилась без "кракозябр".

```cpp
    vector<Racehorse> items = { ... };
```
- Создаётся контейнер `vector` с объектами класса `Racehorse`. В C++ вместо обычных массивов принято использовать `vector`, так как он автоматически управляет памятью и может менять свой размер.

```cpp
    for (const auto& item : items) {
        item.print();
    }
```
- Это *Range-based for loop* (цикл по диапазону). Он автоматически проходит по всем элементам вектора.
- `const auto& item` означает, что мы берём каждый объект по **константной ссылке**. Это предотвращает лишнее копирование данных в памяти и защищает объект от случайных изменений.

### Логика задания
Вывести параметры лошадей и среднее время по всей конюшне.
Для выполнения индивидуального задания мы проходим по контейнеру и используем публичные методы класса для проверки условий и вычисления результатов.

